22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /**
60	     * Monotonically increasing sequence assigned to each {@code OWNER_CREATED} structured event, in
61	     * the order owners are created across this application instance. Shared across all requests.
62	     */
63	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
64	        new java.util.concurrent.atomic.AtomicLong();
65	
66	    /** Serializes the immutable {@link OwnerCreatedEvent} to its canonical JSON form. */
67	    private static final tools.jackson.databind.ObjectMapper AUDIT_EVENT_MAPPER =
68	        tools.jackson.databind.json.JsonMapper.builder().build();
69	
70	    /**
71	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
72	     * is created. Its component order is also its JSON field order: {@code seq}, {@code ownerId},
73	     * {@code memberId}, {@code membershipLevel}, {@code event}. The {@code memberId} component carries
74	     * the owner's unified primary identifier.
75	     */
76	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
77	        Integer membershipLevel, String event) {
78	    }
79	
80	    /**
81	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
82	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
83	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
84	     */
85	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
86	        new java.util.concurrent.ConcurrentHashMap<>();
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
135	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
136	        // the identity/household duplicate rules would otherwise reject with 409).
137	        String idempotencyKey = currentIdempotencyKey();
138	        if (idempotencyKey != null) {
139	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
140	            if (existingId != null) {
141	                Owner existing = this.clinicService.findOwnerById(existingId);
142	                if (existing != null) {
143	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
144	                }
145	            }
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        applyAddress(owner);
150	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
151	        owner.setTelephone(normalizedTelephone);
152	        owner.setEmail(normalizeEmail(owner.getEmail()));
153	        validateEmailDomain(owner.getEmail());
154	        validatePostcode(owner.getPostcode(), owner.getCity());
155	        java.time.LocalDate serverDate = java.time.LocalDate.now();
156	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
157	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
158	                "Registration date must not be later than the current server date");
159	        }
160	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
161	            ? owner.getRegistrationDate() : serverDate;
162	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
163	        owner.setRegistrationDate(businessDate);
164	        long createdToday = this.clinicService.findAllOwners().stream()
165	            .map(Owner::getRegistrationDate)
166	            .filter(businessDate::equals)
167	            .count();
168	        if (createdToday >= 100) {
169	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
170	                "The maximum number of owners for today has already been reached");
171	        }
172	        owner.setBulkSignupWarning(createdToday > 80);
173	        // The household is keyed deterministically on (normalized last name, postcode): every owner
174	        // computes the same householdId from those two fields, so owners sharing a last name and
175	        // postcode belong to the same household automatically, without any explicit linking.
176	        String lastNameKey = normalizeForHousehold(owner.getLastName());
177	        String householdId = householdId(lastNameKey, owner.getPostcode());
178	        owner.setHouseholdId(householdId);
179	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
180	        // no longer blocks a new owner that would otherwise match it.
181	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> !existing.isDeleted())
183	            .filter(existing -> householdId.equals(
184	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
185	            .toList();
186	        // All duplicate detection is expressed through the single derived identityKey, the SHA-256
187	        // hex of (normalizedTelephone|lowerEmail|soundex(lastName)); a new owner is rejected only
188	        // when its whole key matches an existing (non-deleted) owner's.
189	        String identityKey = owner.getIdentityKey();
190	        boolean identityInUse = this.clinicService.findAllOwners().stream()
191	            .filter(existing -> !existing.isDeleted())
192	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
193	        if (identityInUse) {
194	            throw new ResponseStatusException(HttpStatus.CONFLICT,
195	                "An owner with this identity already exists");
196	        }
197	        // Duplicate detection is now the single identity key above; because the telephone is part of
198	        // that key, two owners sharing a last name and postcode but with different telephones have
199	        // different keys and are both admitted, so the former household-duplicate 409 no longer
200	        // applies. Declaring 'sharesHousehold' marks the new owner as a declared household member.
201	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
202	        // An undeclared new owner joining an existing household while carrying its own (distinct)
203	        // email address joins as a member whose membership level is capped below.
204	        boolean distinguishableByEmail = owner.getEmail() != null && !owner.getEmail().isBlank()
205	            && householdMembers.stream()
206	                .noneMatch(existing -> owner.getEmail().equalsIgnoreCase(existing.getEmail()));
207	        boolean joinsExistingHousehold = !householdMembers.isEmpty()
208	            && !declaredHouseholdMember && distinguishableByEmail;
209	        String cityKey = normalizeForHousehold(owner.getCity());
210	        long cityCount = this.clinicService.findAllOwners().stream()
211	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
212	            .count();
213	        if (cityCount >= 50) {
214	            throw new ResponseStatusException(HttpStatus.CONFLICT,
215	                "This city already has the maximum number of owners");
216	        }
217	        // Approaching the per-city capacity limit (50): warn once the city already holds 40-49
218	        // owners. Fixed at creation time, mirroring bulkSignupWarning. The >= 50 case is rejected
219	        // above, so cityCount is guaranteed below 50 here.
220	        owner.setCapacityWarning(cityCount >= 40);
221	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
222	        owner.setHouseholdSize(householdMembers.size() + 1);
223	        // A new owner joining an existing household cannot rank more than one level above the current
224	        // maximum membership level among their household members: its level is capped there. With no
225	        // existing household member (the usual case) no cap applies and the level stays as derived.
226	        if (joinsExistingHousehold) {
227	            int naturalLevel = Owner.membershipLevel(Owner.membershipPoints(owner));
228	            int maxMemberLevel = householdMembers.stream()
229	                .mapToInt(Owner::effectiveMembershipLevel)
230	                .max().orElse(0);
231	            owner.setMembershipLevel(Math.min(naturalLevel, maxMemberLevel + 1));
232	        }
233	        // Soft match: a new owner whose identityKey differs from every existing owner but whose
234	        // soundex(lastName) and postcode both match an existing (non-deleted) owner is flagged as a
235	        // possible duplicate of the earliest such owner. Soft-deleted owners are ignored, matching
236	        // the identity check above.
237	        String lastNameSoundex = Owner.soundex(owner.getLastName());
238	        Owner softMatch = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> !existing.isDeleted())
240	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
241	            .filter(existing -> owner.getPostcode() != null
242	                && owner.getPostcode().equals(existing.getPostcode()))
243	            .filter(existing -> lastNameSoundex.equals(Owner.soundex(existing.getLastName())))
244	            .min(java.util.Comparator.comparing(Owner::getId))
245	            .orElse(null);
246	        if (softMatch != null) {
247	            owner.setPossibleDuplicate(true);
248	            owner.setPossibleDuplicateOf(softMatch.getId());
249	        } else {
250	            owner.setPossibleDuplicate(false);
251	            owner.setPossibleDuplicateOf(null);
252	        }
253	        owner.setMemberId(deduplicateMemberId(memberId(owner.getCity(), owner.getPostcode(),
254	            owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate())));
255	        this.clinicService.saveOwner(owner);
256	        if (idempotencyKey != null) {
257	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
258	        }
259	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
260	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
261	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
262	        // The event's primary identifier is the owner's unified memberId.
263	        String primaryIdentifier = owner.getMemberId();
264	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_EVENT_SEQ.incrementAndGet(),
265	            owner.getId(), primaryIdentifier, ownerDto.getMembershipLevel(), "OWNER_CREATED");
266	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
267	        headers.setLocation(UriComponentsBuilder.newInstance()
268	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
269	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
270	    }
271	
272	    /**
273	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
274	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
275	     * request without the header behaves exactly as before).
276	     *
277	     * @return the non-blank idempotency key for the current request, or {@code null}
278	     */
279	    private String currentIdempotencyKey() {
280	        org.springframework.web.context.request.RequestAttributes attrs =
281	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
282	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
283	            return null;
284	        }
285	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
286	        if (key == null || key.isBlank()) {
287	            return null;
288	        }
289	        return key.trim();
290	    }
291	
292	    /**
293	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
294	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
295	     */
296	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
297	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
298	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
299	        java.time.LocalDate.parse("2026-12-28"));
300	
301	    /**
302	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
303	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
304	     * a plain weekday is returned unchanged. This is applied to the effective registration date
305	     * (whether supplied in the request or defaulted to the server date) so that every stored
306	     * {@code registrationDate}, and any value derived from it, lands on a business day.
307	     *
308	     * @param date the effective registration date
309	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
310	     */
311	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
312	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
313	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
314	            || PUBLIC_HOLIDAYS.contains(date)) {
315	            date = date.plusDays(1);
316	        }
317	        return date;
318	    }
319	
320	    /**
321	     * Counts the owners that already exist (before the current create) whose first and last names
322	     * both match the supplied names, compared case-insensitively. The returned value is captured on
323	     * the new owner at creation time and does not change as further owners are added later.
324	     *
325	     * @param firstName the new owner's first name
326	     * @param lastName  the new owner's last name
327	     * @return the number of pre-existing namesake owners
328	     */
329	    private int namesakeCount(String firstName, String lastName) {
330	        return (int) this.clinicService.findAllOwners().stream()
331	            .filter(existing -> existing.getFirstName() != null
332	                && existing.getFirstName().equalsIgnoreCase(firstName)
333	                && existing.getLastName() != null
334	                && existing.getLastName().equalsIgnoreCase(lastName))
335	            .count();
336	    }
337	
338	    /**
339	     * Builds the unified member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'}.
340	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
341	     * the city when the postcode is absent or in no known range, see
342	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}).
343	     * {@code FY} is the 2-digit fiscal year of the (business-day-adjusted) registration date.
344	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
345	     * normalized telephone concatenated with the last name (the same HASH8 the region-and-hash
346	     * identity used). {@code CHK} is a single Luhn check digit computed over the digits of the
347	     * {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}). It is a pure function of
348	     * the owner's region, fiscal year, telephone and last name.
349	     *
350	     * @param city                the owner's city
351	     * @param postcode            the owner's postcode, may be {@code null}
352	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
353	     * @param lastName            the owner's last name
354	     * @param registrationDate    the owner's business-day-adjusted registration date
355	     * @return the assigned member id
356	     */
357	    private String memberId(String city, String postcode, String normalizedTelephone, String lastName,
358	            java.time.LocalDate registrationDate) {
359	        String region = org.springframework.samples.petclinic.mapper.Localities
360	            .forCityAndPostcode(city, postcode);
361	        String fy = Owner.fiscalYearLabel(registrationDate).substring(2);
362	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
363	            + (lastName == null ? "" : lastName), 8);
364	        String prefix = region + fy + hash8;
365	        return prefix + Owner.luhnCheckDigit(prefix);
366	    }
367	
368	    /**
369	     * Ensures the computed {@code memberId} is unique across existing owners. When {@code baseId}
370	     * does not collide with any existing owner's {@code memberId} it is returned unchanged.
371	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
372	     * value not already in use, and that de-duplicated id is returned.
373	     *
374	     * @param baseId the freshly computed member id
375	     * @return {@code baseId} if unused, otherwise {@code baseId + "-" + n} for the smallest free n
376	     */
377	    private String deduplicateMemberId(String baseId) {
378	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
379	            .map(org.springframework.samples.petclinic.model.Owner::getMemberId)
380	            .filter(java.util.Objects::nonNull)
381	            .collect(java.util.stream.Collectors.toSet());
382	        if (!inUse.contains(baseId)) {
383	            return baseId;
384	        }
385	        int n = 2;
386	        while (inUse.contains(baseId + "-" + n)) {
387	            n++;
388	        }
389	        return baseId + "-" + n;
390	    }
391	
392	    /**
393	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
394	     * UTF-8 bytes of {@code value}.
395	     *
396	     * @param value  the source value to hash
397	     * @param length the number of leading hex characters to return
398	     * @return the leading upper-case hex characters of the digest
399	     */
400	    private String sha256UpperHex(String value, int length) {
401	        try {
402	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
403	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
404	            StringBuilder sb = new StringBuilder(digest.length * 2);
405	            for (byte b : digest) {
406	                sb.append(String.format("%02x", b));
407	            }
408	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
409	        }
410	        catch (java.security.NoSuchAlgorithmException e) {
411	            throw new IllegalStateException("SHA-256 not available", e);
412	        }
413	    }
414	
415	    /**
416	     * Normalizes a street address applied whenever an owner is created: leading and trailing
417	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
418	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
419	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
420	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
421	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
422	     * {@code '12 MAIN STREET'}.
423	     *
424	     * @param address the raw address as submitted, or {@code null} when absent
425	     * @return the normalized address, or the empty string when the value is blank
426	     */
427	    /**
428	     * Resolves and normalizes an owner's postal address, accepting either the structured form
429	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
430	     * input for backward compatibility. The structured form is preferred: when a non-blank
431	     * {@code addressLine1} is supplied, both structured lines are normalized (see
432	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
433	     * the normalized {@code addressLine1}, with a single space and the normalized
434	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
435	     * {@code address} input is normalized and stored, and the structured lines are cleared.
436	     *
437	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
438	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
439	     *
440	     * @param owner the owner whose address fields are resolved and normalized in place
441	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
442	     */
443	    private void applyAddress(Owner owner) {
444	        String line1 = normalizeAddress(owner.getAddressLine1());
445	        String line2 = normalizeAddress(owner.getAddressLine2());
446	        String flat = normalizeAddress(owner.getAddress());
447	        String composed;
448	        if (!line1.isEmpty()) {
449	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
450	            owner.setAddressLine1(line1);
451	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
452	        } else {
453	            composed = flat;
454	            owner.setAddressLine1(null);
455	            owner.setAddressLine2(null);
456	        }
457	        if (composed.isEmpty()) {
458	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
459	                "Address must not be blank after normalization");
460	        }
461	        owner.setAddress(composed);
462	    }
463	
464	    private String normalizeAddress(String address) {
465	        String collapsed = (address == null ? "" : address)
466	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
467	        if (collapsed.isEmpty()) {
468	            return "";
469	        }
470	        String[] tokens = collapsed.split(" ");
471	        for (int i = 0; i < tokens.length; i++) {
472	            switch (tokens[i]) {
473	                case "ST" -> tokens[i] = "STREET";
474	                case "RD" -> tokens[i] = "ROAD";
475	                case "AVE" -> tokens[i] = "AVENUE";
476	                default -> { }
477	            }
478	        }
479	        return String.join(" ", tokens);
480	    }
481	
482	    /**
483	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
484	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
485	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
486	     * empty string.
487	     *
488	     * @param value the raw value (last name or address) as submitted
489	     * @return the normalized comparison key
490	     */
491	    private String normalizeForHousehold(String value) {
492	        if (value == null) {
493	            return "";
494	        }
495	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
496	    }
497	
498	    /**
499	     * Derives the stable shared household identifier for a household, keyed on the normalized last
500	     * name and address. Because it is a pure function of those normalized keys, every owner in the
501	     * same household deterministically computes the same value. The identifier is the first 12
502	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
503	     * (the separator prevents distinct name/address pairs from colliding).
504	     *
505	     * @param lastNameKey the normalized last-name comparison key
506	     * @param addressKey  the normalized address comparison key
507	     * @return the stable household identifier
508	     */
509	    private String householdId(String lastNameKey, String postcode) {
510	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
511	        try {
512	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
513	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
514	            StringBuilder sb = new StringBuilder(digest.length * 2);
515	            for (byte b : digest) {
516	                sb.append(String.format("%02x", b));
517	            }
518	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
519	        }
520	        catch (java.security.NoSuchAlgorithmException e) {
521	            throw new IllegalStateException("SHA-256 not available", e);
522	        }
523	    }
524	
525	    /**
526	     * The exact number of national (subscriber) digits required for a given country calling code,
527	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
528	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
529	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
530	     */
531	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
532	        java.util.Map.of("61", 9, "1", 10);
533	
534	    /**
535	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
536	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
537	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
538	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
539	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
540	     * is stored as {@code '+61412345678'}.
541	     *
542	     * <p>In addition, when the number's country code has a fixed national-number length (see
543	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
544	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
545	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
546	     *
547	     * @param telephone the raw telephone number as submitted
548	     * @return the normalized E.164 telephone number
549	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
550	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
551	     *         for its country code
552	     */
553	    private String normalizeTelephone(String telephone) {
554	        String raw = telephone == null ? "" : telephone.trim();
555	        String digits = raw.replaceAll("\\D", "");
556	        String e164;
557	        if (raw.startsWith("+")) {
558	            e164 = "+" + digits;
559	        } else {
560	            if (digits.startsWith("0")) {
561	                digits = digits.substring(1);
562	            }
563	            e164 = "+61" + digits;
564	        }
565	        int digitCount = e164.length() - 1;
566	        if (digitCount < 8 || digitCount > 15) {
567	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
568	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
569	        }
570	        validateNationalNumberLength(e164);
571	        return e164;
572	    }
573	
574	    /**
575	     * Validates that an E.164 number's national-number length is correct for its country code.
576	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
577	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
578	     * following it must match exactly. Country codes without a fixed length are left unchecked.
579	     *
580	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
581	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
582	     *         for the country code
583	     */
584	    private void validateNationalNumberLength(String e164) {
585	        String allDigits = e164.substring(1);
586	        String bestCode = null;
587	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
588	            if (allDigits.startsWith(code)
589	                    && (bestCode == null || code.length() > bestCode.length())) {
590	                bestCode = code;
591	            }
592	        }
593	        if (bestCode == null) {
594	            return;
595	        }
596	        int nationalLength = allDigits.length() - bestCode.length();
597	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
598	        if (nationalLength != required) {
599	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
600	                "Telephone for country code '+" + bestCode + "' must have " + required
601	                    + " national digits");
602	        }
603	    }
604	
605	    /**
606	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
607	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
608	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
609	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
610	     */
611	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
612	        "NSW", new int[] {2000, 2099},
613	        "VIC", new int[] {3000, 3099},
614	        "QLD", new int[] {4000, 4099});
615	
616	    /**
617	     * Validates an owner's optional postcode against their city's region. The postcode is only
618	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
619	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
620	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
621	     * postcode must fall within that region's inclusive range; a city with no known region accepts
622	     * any 4-digit postcode.
623	     *
624	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
625	     * @param city     the owner's city, used to derive the region whose range applies
626	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
627	     *         for the city's region
628	     */
629	    private void validatePostcode(String postcode, String city) {
630	        if (postcode == null) {
631	            return;
632	        }
633	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
634	        int[] range = REGION_POSTCODE_RANGES.get(region);
635	        if (range == null) {
636	            return;
637	        }
638	        int value = Integer.parseInt(postcode);
639	        if (value < range[0] || value > range[1]) {
640	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
641	                "Postcode " + postcode + " is not valid for region " + region);
642	        }
643	    }
644	
645	    /**
646	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
647	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
648	     * (absent) or already valid.
649	     *
650	     * @param email the email address as submitted, or {@code null} when absent
651	     * @return the lower-cased email, or {@code null} when absent
652	     */
653	    private String normalizeEmail(String email) {
654	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
655	    }
656	
657	    /**
658	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
659	     * providers are rejected because they cannot be relied on for durable contact.
660	     */
661	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
662	        "mailinator.com", "tempmail.com", "guerrillamail.com");
663	
664	    /**
665	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
666	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
667	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
668	     * (absent) is accepted, keeping the field optional.
669	     *
670	     * @param email the normalized email address, or {@code null} when absent
671	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
672	     */
673	    private void validateEmailDomain(String email) {
674	        if (email == null) {
675	            return;
676	        }
677	        int at = email.lastIndexOf('@');
678	        if (at < 0) {
679	            return;
680	        }
681	        String domain = email.substring(at + 1);
682	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
683	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
684	                "Email domain " + domain + " is not allowed");
685	        }
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
691	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
692	        if (currentOwner == null) {
693	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
694	        }
695	        currentOwner.setAddress(ownerFieldsDto.getAddress());
696	        currentOwner.setCity(ownerFieldsDto.getCity());
697	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
698	        currentOwner.setLastName(ownerFieldsDto.getLastName());
699	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
700	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
701	        this.clinicService.saveOwner(currentOwner);
702	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
703	    }
704	
705	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
706	    @Transactional
707	    @Override
708	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
709	        Owner owner = this.clinicService.findOwnerById(ownerId);
710	        if (owner == null) {
711	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
712	        }
713	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
714	        owner.setDeleted(true);
715	        this.clinicService.saveOwner(owner);
716	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
717	    }
718	
719	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
720	    @Override
721	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
722	        Owner owner = this.clinicService.findOwnerById(ownerId);
723	        if (owner == null) {
724	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
725	        }
726	        HttpHeaders headers = new HttpHeaders();
727	        Pet pet = petMapper.toPet(petFieldsDto);
728	        owner.setId(ownerId);
729	        pet.setOwner(owner);
730	        pet.getType().setName(null);
731	        this.clinicService.savePet(pet);
732	        PetDto petDto = petMapper.toPetDto(pet);
733	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
734	            .buildAndExpand(pet.getId()).toUri());
735	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
736	    }
737	
738	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
739	    @Override
740	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
741	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
742	        if (currentOwner != null) {
743	            Pet currentPet = this.clinicService.findPetById(petId);
744	            if (currentPet != null) {
745	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
746	                currentPet.setName(petFieldsDto.getName());
747	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
748	                this.clinicService.savePet(currentPet);
749	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
750	            }
751	        }
752	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
753	    }
754	
755	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
756	    @Override
757	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
758	        HttpHeaders headers = new HttpHeaders();
759	        Visit visit = visitMapper.toVisit(visitFieldsDto);
760	        Pet pet = new Pet();
761	        pet.setId(petId);
762	        visit.setPet(pet);
763	        this.clinicService.saveVisit(visit);
764	        VisitDto visitDto = visitMapper.toVisitDto(visit);
765	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
766	            .buildAndExpand(visit.getId()).toUri());
767	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
768	    }
769	
770	
771	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
772	    @Override
773	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
774	        Owner owner = this.clinicService.findOwnerById(ownerId);
775	        if (owner != null) {
776	            Pet pet = owner.getPet(petId);
777	            if (pet != null) {
778	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
779	            }
780	        }
781	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
782	    }
783	}
